const results = await Promise.allSettled([
  tools.exec_command({cmd:"ls -la /app && rg --files /app | head -100",workdir:"/app",yield_time_ms:10000,max_output_tokens:3000}),
  tools.exec_command({cmd:"sed -n '1,260p' /opt/tools/rcb_client.py",workdir:"/app",yield_time_ms:10000,max_output_tokens:5000}),
  tools.exec_command({cmd:"python - <<'PY'\nfrom PIL import Image\nim=Image.open('/app/target.png')\nprint(im.size, im.mode)\nprint(im.getpixel((0,0)), im.getpixel((512,512)))\nPY",workdir:"/app",yield_time_ms:10000,max_output_tokens:1000})
]);
for (let i=0;i<results.length;i++){const r=results[i]; text(JSON.stringify({i,status:r.status,result:r.status==="fulfilled"?r.value:r.reason}));}

const results = await Promise.allSettled([
  tools.view_image({path:"/app/output/park_canvas_cam.png",detail:"high"}),
  tools.view_image({path:"/app/output/park_practice_cam.png",detail:"high"}),
]);
for (const r of results){ if(r.status==="fulfilled") image(r.value.image_url); else text(String(r.reason));}

